function loadDB(){try{const x=JSON.parse(localStorage.getItem("hostelLaundry_v1"));if(x&&x.version===1){const loaded={...structuredClone(DEFAULT),...x,config:{...DEFAULT.config,...x.config}};loaded.records=(loaded.records||[]).map(r=>({...r,unit:r.unit||"SR",item:r.item==="Cobertor fino de casal"?"Cobertor de casal":r.item}));
loaded.qualityRecords=(Array.isArray(loaded.qualityRecords)?loaded.qualityRecords:[]).map(r=>({...r,unit:r.unit||"SR",item:r.item==="Cobertor fino de casal"?"Cobertor de casal":r.item}));
loaded.stockByUnit=loaded.stockByUnit||{SR:loaded.stock||null,MK:null};loaded.rotationByUnit=loaded.rotationByUnit||{SR:null,MK:null};loaded.configByUnit=loaded.configByUnit||{SR:{...DEFAULT.config,...loaded.config},MK:{...DEFAULT.config}};loaded.config={...loaded.configByUnit.SR};loaded.stockHistory=(loaded.stockHistory||[]).map(s=>({...s,unit:s.unit||"SR"}));
for(const stock of Object.values(loaded.stockByUnit)){if(stock?.items?.["Cobertor fino de casal"]){const old=stock.items["Cobertor fino de casal"];stock.items["Cobertor de casal"]=stock.items["Cobertor de casal"]||{};for(const k of ["clean","inUse","dirty","unusable"])if(old[k]!==undefined)stock.items["Cobertor de casal"][k]=num(stock.items["Cobertor de casal"][k])+num(old[k]);delete stock.items["Cobertor fino de casal"];}}return loaded;}}catch(e){}return {...structuredClone(DEFAULT),stockByUnit:{SR:null,MK:null},configByUnit:{SR:{...DEFAULT.config},MK:{...DEFAULT.config}}}}
