function today(){let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function num(v){return Number.isFinite(Number(v))?Number(v):0}
function fmt(n){return Math.round(n).toLocaleString("pt-BR")}
function dateFmt(s){if(!s)return "—";const [y,m,d]=s.split("-");return `${d}/${m}/${y}`}
function switchTab(id){document.querySelectorAll(".tab").forEach(b=>b.classList.toggle("active",b.dataset.tab===id));document.querySelectorAll(".view").forEach(v=>v.classList.toggle("active",v.id===id));if(id==="painel")renderDashboard();if(id==="registro")renderRecords();if(id==="estoque")renderStock();if(id==="rotatividade")renderRotation();if(id==="qualidade")renderQuality();if(id==="previsao")renderForecast();if(id==="config")renderConfig();if(id==="dados")renderDataStats();window.scrollTo({top:0,behavior:"smooth"})}
