function saveOtherConfig(){db.config.curtainInterval=Math.max(1,num(document.getElementById("curtainInterval").value)||30);db.configByUnit=db.configByUnit||{SR:{...DEFAULT.config},MK:{...DEFAULT.config}};db.configByUnit[selectedUnit("configUnit")]= {...db.config};persist();alert("Frequência salva para "+unitLabel(selectedUnit("configUnit"))+".");}
const ROTATION_STAGES={dirty:"Suja / saldo inicial",washed:"Lavada",machineDry:"Seca na máquina",lineWet:"Pendente no varal",lineDry:"Seca do varal",clean:"Limpa disponível",inUse:"Em uso no hostel",unusable:"Inservível"};
function suggestedSource(stage){return ({"Lavadas":"dirty","Secas na máquina":"washed","Pendente no varal":"washed","Secas do varal":"lineWet"})[stage]||"dirty"}
function updateFromStage(){const stage=document.getElementById("pStage")?.value,wrap=document.getElementById("pFromStageWrap"),sel=document.getElementById("pFromStage");if(!wrap||!sel)return;const active=!!db.rotationByUnit?.[selectedUnit("pUnit")];wrap.classList.toggle("hidden",!active||stage==="Recebidas"||stage==="Pendentes ao fim do dia");if(["Lavadas","Secas na máquina","Pendente no varal","Secas do varal"].includes(stage))sel.value=suggestedSource(stage);else if(["Passadas/finalizadas","Descartadas"].includes(stage))sel.value="dirty";}
function ensureRotation(unit){db.rotationByUnit=db.rotationByUnit||{SR:null,MK:null};return db.rotationByUnit[unit]}
function startRotation(){const unit=selectedUnit("rotationUnit"),stock=db.stockByUnit?.[unit]||((unit==="SR")?db.stock:null);if(ensureRotation(unit)?.active){alert("A rotatividade desta unidade já foi iniciada. O saldo de abertura não pode ser substituído por outro inventário, para evitar duplicidade.");return;}if(!stock){alert("Salve primeiro o inventário físico desta unidade.");return;}const missing=[];for(const [name] of ITEMS){const row=stock.items?.[name]||{};for(const key of ["clean","inUse","dirty","unusable"])if(row[key]===undefined||row[key]===null||row[key]==="")missing.push(name+" · "+({clean:"Limpa",inUse:"Em uso",dirty:"Suja",unusable:"Inservível"})[key]);}if(missing.length){alert("Para iniciar com um saldo confiável, complete os 4 campos de todas as peças no inventário. Onde não houver peças, informe 0. Ainda faltam "+missing.length+" campo(s). Primeiro exemplo: "+missing.slice(0,5).join("; ")) ;return;}if(!confirm("Iniciar a rotatividade de "+unitLabel(unit)+" usando o inventário salvo de "+dateFmt(stock.date)+"? As quantidades atuais serão o saldo de abertura. Os registros de produção anteriores não serão reaplicados."))return;const items={};for(const [name] of ITEMS){const row=stock.items[name];items[name]={total:num(row.clean)+num(row.inUse)+num(row.dirty)+num(row.unusable),stages:{clean:num(row.clean),inUse:num(row.inUse),dirty:num(row.dirty),unusable:num(row.unusable),washed:0,machineDry:0,lineWet:0,lineDry:0},delivered:0,discarded:0,purchased:0,received:0};}db.rotationByUnit[unit]={active:true,unit,startedAt:new Date().toISOString(),openingDate:stock.date,items,movements:[]};persist();renderAll();renderRotation();alert("Rotatividade iniciada. O inventário foi usado uma única vez como saldo de abertura.");}
function applyRotationRecord(rec){const unit=rec.unit||"SR",rot=ensureRotation(unit);if(!rot?.active)return {applied:false};const item=rot.items[rec.item];if(!item)return {applied:false};const qty=num(rec.qty),stage=rec.stage,from=rec.fromStage||"dirty",st=item.stages;let movement={date:rec.date,unit,item:rec.item,qty,action:stage,fromStage:null,toStage:null,notes:rec.notes||"",recordId:rec.id};
if(stage==="Pendentes ao fim do dia")return {applied:false};
if(stage==="Recebidas"){if(st.inUse<qty)return {error:`Saldo insuficiente em “Em uso no hostel” para ${rec.item}. Disponível: ${fmt(st.inUse)}; lançamento: ${fmt(qty)}.`};st.inUse-=qty;st.dirty+=qty;item.received+=qty;movement.fromStage="inUse";movement.toStage="dirty";}
else if(stage==="Lavadas"){if(st[from]<qty)return {error:`Saldo insuficiente em “${ROTATION_STAGES[from]}” para ${rec.item}. Disponível: ${fmt(st[from])}; lançamento: ${fmt(qty)}.`};st[from]-=qty;st.washed+=qty;movement.fromStage=from;movement.toStage="washed";}
else if(stage==="Secas na máquina"){if(st[from]<qty)return {error:`Saldo insuficiente em “${ROTATION_STAGES[from]}” para ${rec.item}. Disponível: ${fmt(st[from])}; lançamento: ${fmt(qty)}.`};st[from]-=qty;st.machineDry+=qty;movement.fromStage=from;movement.toStage="machineDry";}
else if(stage==="Pendente no varal"){if(st[from]<qty)return {error:`Saldo insuficiente em “${ROTATION_STAGES[from]}” para ${rec.item}. Disponível: ${fmt(st[from])}; lançamento: ${fmt(qty)}.`};st[from]-=qty;st.lineWet+=qty;movement.fromStage=from;movement.toStage="lineWet";}
else if(stage==="Secas do varal"){if(st[from]<qty)return {error:`Saldo insuficiente em “${ROTATION_STAGES[from]}” para ${rec.item}. Disponível: ${fmt(st[from])}; lançamento: ${fmt(qty)}.`};st[from]-=qty;st.lineDry+=qty;movement.fromStage=from;movement.toStage="lineDry";}
else if(stage==="Passadas/finalizadas"){if(from==="unusable"){return {error:"Peças marcadas como inservíveis não podem ser finalizadas/entregues. Registre recuperação na Qualidade ou descarte."};}if(st[from]<qty)return {error:`Saldo insuficiente em “${ROTATION_STAGES[from]}” para ${rec.item}. Disponível: ${fmt(st[from])}; lançamento: ${fmt(qty)}.`};st[from]-=qty;st.inUse+=qty;item.delivered+=qty;movement.fromStage=from;movement.toStage="delivered";}
else if(stage==="Descartadas"){if(st[from]<qty)return {error:`Saldo insuficiente em “${ROTATION_STAGES[from]}” para ${rec.item}. Disponível: ${fmt(st[from])}; lançamento: ${fmt(qty)}.`};st[from]-=qty;item.total=Math.max(0,item.total-qty);item.discarded+=qty;movement.fromStage=from;movement.toStage="discarded";}
else return {applied:false};rot.movements.unshift({...movement,createdAt:new Date().toISOString()});rec.rotationApplied=true;rec.fromStage=from;rec.rotationMovement=movement;return {applied:true};}
function renderRotation(){const unit=selectedUnit("rotationUnit"),rot=ensureRotation(unit),summary=document.getElementById("rotationSummary");if(!summary)return;const startBtn=document.getElementById("startRotationBtn");if(!rot?.active){summary.innerHTML='<div class="empty">Rotatividade ainda não iniciada nesta unidade. Salve e revise o inventário físico antes de iniciar.</div>';startBtn.disabled=false;startBtn.textContent="Iniciar rotatividade com inventário salvo";document.getElementById("rotationTable").innerHTML="";document.getElementById("rotationHistory").innerHTML='<div class="empty">Nenhuma movimentação registrada.</div>';return;}startBtn.disabled=true;startBtn.textContent="Saldo de abertura já iniciado";let total=0,dirty=0,washed=0,machineDry=0,lineWet=0,lineDry=0,clean=0,inUse=0,unusable=0,delivered=0,discarded=0,purchased=0;for(const it of Object.values(rot.items)){total+=it.total;dirty+=it.stages.dirty;washed+=it.stages.washed;machineDry+=it.stages.machineDry;lineWet+=it.stages.lineWet;lineDry+=it.stages.lineDry;clean+=it.stages.clean;inUse+=it.stages.inUse;unusable+=it.stages.unusable;delivered+=it.delivered;discarded+=it.discarded;purchased+=it.purchased;}summary.innerHTML=`<p class="small muted">Saldo iniciado em ${dateFmt(rot.openingDate)} · ${unitLabel(unit)}. O inventário físico continua separado e não altera este saldo automaticamente.</p><div class="grid rotation-metrics"><div><div class="metric">${fmt(total)}</div><div class="small muted">Total do enxoval</div></div><div><div class="metric">${fmt(dirty)}</div><div class="small muted">Suja / saldo inicial</div></div><div><div class="metric">${fmt(washed)}</div><div class="small muted">Lavada</div></div><div><div class="metric">${fmt(machineDry+lineWet+lineDry)}</div><div class="small muted">Em secagem</div></div><div><div class="metric">${fmt(clean)}</div><div class="small muted">Limpa disponível</div></div><div><div class="metric">${fmt(inUse)}</div><div class="small muted">Em uso no hostel</div></div><div><div class="metric">${fmt(unusable)}</div><div class="small muted">Inservível</div></div><div><div class="metric">${fmt(delivered)}</div><div class="small muted">Finalizadas/entregues (acumulado)</div></div><div><div class="metric">${fmt(discarded)}</div><div class="small muted">Descartadas (acumulado)</div></div><div><div class="metric">${fmt(purchased)}</div><div class="small muted">Compradas desde a abertura</div></div></div>`;const rows=ITEMS.map(([name])=>{const it=rot.items[name],st=it.stages;return `<tr><td>${esc(name)}</td><td>${fmt(it.total)}</td><td>${fmt(st.dirty)}</td><td>${fmt(st.washed)}</td><td>${fmt(st.machineDry)}</td><td>${fmt(st.lineWet)}</td><td>${fmt(st.lineDry)}</td><td>${fmt(st.clean)}</td><td>${fmt(st.inUse)}</td><td>${fmt(st.unusable)}</td><td>${fmt(it.delivered)}</td><td>${fmt(it.discarded)}</td></tr>`}).join("");document.getElementById("rotationTable").innerHTML=`<div class="tablewrap"><table><thead><tr><th>Peça</th><th>Total</th><th>Suja</th><th>Lavada</th><th>Seca máquina</th><th>No varal</th><th>Seca varal</th><th>Limpa</th><th>Em uso</th><th>Inservível</th><th>Entregue acum.</th><th>Descartada acum.</th></tr></thead><tbody>${rows}</tbody></table></div>`;const history=(rot.movements||[]).slice(0,20);document.getElementById("rotationHistory").innerHTML=history.length?`<div class="tablewrap"><table><thead><tr><th>Data</th><th>Peça</th><th>Qtd.</th><th>Movimento</th></tr></thead><tbody>${history.map(m=>`<tr><td>${dateFmt(m.date)}</td><td>${esc(m.item)}</td><td>${fmt(m.qty)}</td><td>${esc(m.action)}${m.fromStage?` · ${esc(ROTATION_STAGES[m.fromStage]||m.fromStage)} → ${m.toStage==="delivered"?"Finalizadas/entregues":m.toStage==="discarded"?"Descartadas":esc(ROTATION_STAGES[m.toStage]||m.toStage)}`:""}</td></tr>`).join("")}</tbody></table></div>`:'<div class="empty">Nenhuma movimentação registrada.</div>';}
function registerPurchase(e){e.preventDefault();const unit=selectedUnit("rotationUnit"),rot=ensureRotation(unit),itemName=document.getElementById("purchaseItem").value,qty=Math.max(1,Math.floor(num(document.getElementById("purchaseQty").value))),stage=document.getElementById("purchaseStage").value,date=document.getElementById("purchaseDate").value,notes=document.getElementById("purchaseNotes").value.trim();if(!rot?.active){alert("Inicie a rotatividade desta unidade antes de registrar compras.");return;}const item=rot.items[itemName];item.total+=qty;item.stages[stage]+=qty;item.purchased+=qty;rot.movements.unshift({date,unit,item:itemName,qty,action:"Compra de enxoval",fromStage:null,toStage:stage,notes,createdAt:new Date().toISOString()});persist();renderRotation();e.target.reset();document.getElementById("purchaseDate").value=today();document.getElementById("purchaseQty").value=1;alert("Compra registrada. O total do enxoval foi aumentado.");}
