  for(const unit of units){const rot=db.rotationByUnit?.[unit];if(rot?.active){hasRotation=true;for(const item of Object.values(rot.items||{})){const st=item.stages||{};total+=num(st.dirty)+num(st.washed)+num(st.machineDry)+num(st.lineWet)+num(st.lineDry);}}else{const balances=new Map();db.records.filter(r=>(r.unit||"SR")===unit&&(!unitMatch||unitMatch(r))).forEach(r=>{if(!["Recebidas","Passadas/finalizadas","Descartadas"].includes(r.stage))return;const key=r.item;if(!balances.has(key))balances.set(key,{received:0,finished:0,discarded:0});const b=balances.get(key),qty=num(r.qty);if(r.stage==="Recebidas")b.received+=qty;else if(r.stage==="Passadas/finalizadas")b.finished+=qty;else b.discarded+=qty;});total+=[...balances.values()].reduce((sum,b)=>sum+Math.max(0,b.received-b.finished-b.discarded),0);}}
