    const measured=[...groups.values()].filter(g=>g.minutes>0),mins=measured.reduce((a,g)=>a+g.minutes,0),rate=mins?measured.reduce((a,g)=>a+g.qty,0)/(mins/60):null,hours=hoursAvailable(unit);
